ssh gpu-l4 'cd /workspace/master-thesis-code/pipeline; python - <<EOF
import json, statistics as st
def load(p):
    d=json.load(open(p)); return d["results"]["agentic"]
def stats(name,r,cap):
    s=r["samples"]; c=[x for x in s if x["correct"]]; w=[x for x in s if not x["correct"]]
    tc=[x["n_tokens"] for x in c]; tw=[x["n_tokens"] for x in w]
    at_cap=[x for x in s if x["n_tokens"]>=cap-1]
    print(f"--- {name}  (cap {cap})")
    print(f"  acc {r[\"accuracy\"]:.3f} [{r[\"accuracy_ci_low\"]:.3f},{r[\"accuracy_ci_high\"]:.3f}]  n={r[\"n_samples\"]}")
    print(f"  all      mean {r[\"mean_token_count\"]:.1f}")
    if tc: print(f"  correct  n={len(tc)} mean {st.mean(tc):.1f} median {st.median(tc):.1f} min {min(tc)} max {max(tc)}")
    if tw: print(f"  wrong    n={len(tw)} mean {st.mean(tw):.1f} median {st.median(tw):.1f} min {min(tw)} max {max(tw)}")
    print(f"  at cap   {len(at_cap)}/{len(s)}  (of wrong: {sum(1 for x in at_cap if not x[\"correct\"])}/{len(tw) if tw else 0})")
    print(f"  steps    mean {r[\"mean_steps\"]}")
for p,cap,n in [("runs/e24-poly-4k-env-only-qwen3-1_7b/eval_report.json",4096,"e24 4k env-only (w0)"),
                ("runs/e12-poly-agentic-env-only-qwen3-1_7b/eval_report.json",2048,"e12 2k env-only (w0)"),
                ("runs/e17-poly-agentic-cosine-w16-qwen3-1_7b/eval_report.json",2048,"e17 2k cosine w16")]:
    try: stats(n,load(p),cap)
    except Exception as e: print("---",n,"MISSING:",type(e).__name__,e)
EOF' 2>/dev/null | grep -v "^\*\*\|^║\|^╔\|^╚"

